module tb;

  localparam int          CLK_PERIOD = 8;
  localparam logic [15:0] PRESCALE   = 16'd5;

  logic        clk = 1'b0;
  logic        rst = 1'b1;
  logic        rxd = 1'b1;
  logic        m_axis_tready = 1'b1;
  logic [15:0] prescale = PRESCALE;
  wire  [7:0]  m_axis_tdata;
  wire         m_axis_tvalid;
  wire         busy;
  wire         overrun_error;
  wire         frame_error;

  always #(CLK_PERIOD / 2) clk = ~clk;

  // Receiver under test, default DATA_WIDTH = 8.
  uart_rx dut (
    .clk(clk), .rst(rst),
    .m_axis_tdata(m_axis_tdata), .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd),
    .busy(busy), .overrun_error(overrun_error), .frame_error(frame_error),
    .prescale(prescale)
  );

  // Reactive back-pressure generator.
  // Every time m_axis_tvalid rises, m_axis_tready is held low for exactly one
  // rising clock edge and then raised, so the word is accepted after exactly
  // one stall cycle (this is what R20 requires for the 0xA5 word).
  logic tv_n   = 1'b0;
  logic stall1 = 1'b0;

  always @(negedge clk) begin
    if (rst) begin
      m_axis_tready <= 1'b1;
      tv_n          <= 1'b0;
      stall1        <= 1'b0;
    end else begin
      if (stall1) begin
        m_axis_tready <= 1'b1;   // second edge of the stall window: accept
        stall1        <= 1'b0;
      end else if (m_axis_tvalid && !tv_n) begin
        m_axis_tready <= 1'b0;   // first edge where tvalid is high: stall
        stall1        <= 1'b1;
      end else begin
        m_axis_tready <= 1'b1;   // default: ready
      end
      tv_n <= m_axis_tvalid;
    end
  end

  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic do_reset();
    rst = 1'b1; wait_clks(3);
    rst = 1'b0; wait_clks(3);
  endtask

  task automatic wait_tvalid_rise();
    do begin
      @(negedge clk);
    end while (!m_axis_tvalid);
  endtask

  task automatic wait_tvalid_fall();
    do begin
      @(negedge clk);
    end while (m_axis_tvalid);
  endtask

  // Well-formed 8N1 frame on rxd, LSB first, each bit prescale*8 clocks.
  task automatic uart_send_byte(input logic [7:0] b);
    int bit_clks = int'(prescale) * 8;
    rxd = 1'b0; wait_clks(bit_clks);       // start
    for (int i = 0; i < 8; i++) begin
      rxd = b[i]; wait_clks(bit_clks);     // data, LSB first
    end
    rxd = 1'b1; wait_clks(bit_clks);       // stop
  endtask

  initial begin
    do_reset();

    // First word 0x3C: accepted (m_axis_tvalid && m_axis_tready && data==0x3C)
    // which sets the seen_first latch inside cov_R20.
    uart_send_byte(8'h3C);
    wait_tvalid_rise();
    wait_tvalid_fall();

    // Idle gap so the receiver is fully quiescent before the next frame.
    wait_clks(8);

    // Second word 0xA5: m_axis_tvalid rises with m_axis_tready low for one
    // cycle, then m_axis_tready high -> accepted after exactly one stall.
    // This is the R20 single-cycle-stall-accept condition.
    uart_send_byte(8'hA5);
    wait_tvalid_rise();
    wait_tvalid_fall();

    // Let coverage settle.
    wait_clks(4);
    $display("PASS tb: 0x3C then 0xA5 accepted with single stall");
    #100;
    $finish;
  end

  initial begin
    #10ms;
    $fatal(1, "timeout");
  end

endmodule

