module tb;

  localparam int CLK_PERIOD = 8;
  localparam logic [15:0] PRESCALE = 16'd5;

  logic        clk = 1'b0;
  logic        rst = 1'b0;
  logic        rxd = 1'b1;
  logic        m_axis_tready = 1'b1;
  logic [15:0] prescale = PRESCALE;
  wire  [7:0]  m_axis_tdata;
  wire         m_axis_tvalid;
  wire         busy, overrun_error, frame_error;

  always #(CLK_PERIOD / 2) clk = ~clk;

  uart_rx #(.DATA_WIDTH(8)) dut (
    .clk(clk), .rst(rst),
    .m_axis_tdata(m_axis_tdata), .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd),
    .busy(busy), .overrun_error(overrun_error), .frame_error(frame_error),
    .prescale(prescale)
  );

  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic do_reset();
    rst = 1'b0; wait_clks(2);
    rst = 1'b1; wait_clks(2);
    rst = 1'b0; wait_clks(2);
  endtask

  // Plain 8N1 byte on rxd (LSB first, prescale*8 clocks per bit).
  task automatic uart_send_byte(input byte unsigned b);
    int bit_clks = int'(prescale) * 8;
    rxd = 1'b0; wait_clks(bit_clks);
    for (int i = 0; i < 8; i++) begin
      rxd = b[i]; wait_clks(bit_clks);
    end
    rxd = 1'b1; wait_clks(bit_clks);
  endtask

  // Send an 8N1 byte; return on the first negedge where m_axis_tvalid is high.
  // m_axis_tready must be low so the delivered word latches high and the
  // delivery negedge is unambiguously captured regardless of exact stop timing.
  task automatic uart_send_byte_capture(input byte unsigned b);
    int bit_clks = int'(prescale) * 8;
    int caught = 0;
    rxd = 1'b0; wait_clks(bit_clks);
    for (int i = 0; i < 8; i++) begin
      rxd = b[i]; wait_clks(bit_clks);
    end
    rxd = 1'b1;
    for (int i = 0; i < bit_clks && !caught; i++) begin
      @(negedge clk);
      if (m_axis_tvalid) caught = 1;
    end
    while (!caught) begin
      @(negedge clk);
      if (m_axis_tvalid) caught = 1;
    end
  endtask

  initial begin
    do_reset();
    m_axis_tready = 1'b1;

    // Word 1 = 0x3C, ready high -> accepted; latches seen_first in cov_R20.
    uart_send_byte(8'h3C);
    wait(m_axis_tvalid);
    $display("[tb] word1 data=0x%02h", m_axis_tdata);
    wait(!m_axis_tvalid);   // accepted (ready high), tvalid falls
    wait_clks(2);

    // Stall the next word exactly one cycle: drive ready low.
    m_axis_tready = 1'b0;

    // Word 2 = 0xA5, delivered while ready low (tvalid latches high).
    uart_send_byte_capture(8'hA5);   // returns at the delivery negedge N_del
    m_axis_tready = 1'b0;            // ready low at the tvalid-rise posedge (cnt=1)
    @(negedge clk);                  // one full clock later
    m_axis_tready = 1'b1;            // ready high -> 0xA5 accepted next posedge

    // 0xA5 accepted exactly one cycle after tvalid rose -> R20 hit.
    wait(!m_axis_tvalid);            // tvalid falls (handshake done)
    wait_clks(4);

    $display("PASS tb R20 (frame_error=%0b overrun=%0b)", frame_error, overrun_error);
    $finish;
  end

  initial begin
    #10ms;
    $fatal(1, "timeout");
  end

endmodule
